#[derive(Default, PartialEq, Debug, Clone, Hash, Eq, Serialize, Deserialize)]
pub struct Block {
    /// Length of the data (this is aligned so there can be a gap between this and
    /// the metadata).
    pub bodyLength: i64,
    /// Length of the metadata
    pub metaDataLength: i32,
    /// Index to the start of the RecordBlock (note this is past the Message header)
    pub offset: i64,
}

impl From<Block> for FbsBlock {
    fn from(obj: Block) -> Self {
        let bodyLength = obj.bodyLength;
        let metaDataLength = obj.metaDataLength;
        let offset = obj.offset;

        Self::new(bodyLength, metaDataLength, offset)
    }
}

impl From<&FbsBlock> for Block {
    fn from(fbs: &FbsBlock) -> Self {
        Self {
            bodyLength: fbs.bodyLength(),
            metaDataLength: fbs.metaDataLength(),
            offset: fbs.offset(),
        }
    }
}

/// ----------------------------------------------------------------------
/// Arrow File metadata
///
#[derive(Default, PartialEq, Debug, Clone, Hash, Eq, Serialize, Deserialize)]
pub struct Footer {
    /// User-defined metadata
    pub custom_metadata: Option<Vec<KeyValue>>,
    pub dictionaries: Option<Vec<Block>>,
    pub recordBatches: Option<Vec<Block>>,
    pub schema: Option<Schema>,
    pub version: MetadataVersion,
}

impl Footer {
    pub fn serialize_to<'a>(
        &self,
        builder: &mut flatbuffers::FlatBufferBuilder<'a>,
    ) -> flatbuffers::WIPOffset<FbsFooter<'a>> {
        use crate::types::generated::File_generated::FooterBuilder as FbsFooterBuilder;

        let custom_metadata_offset = self.custom_metadata.as_ref().map(|v| {
            let mut custom_metadata_offsets = Vec::with_capacity(v.len());
            for val in v.iter() {
                let offset = val.serialize_to(builder);
                custom_metadata_offsets.push(offset);
            }
            let custom_metadata_offset = builder.create_vector(&custom_metadata_offsets);
            custom_metadata_offset
        });
        let dictionaries_offset = self.dictionaries.as_ref().map(|v| {
            let dictionaries_offset =
                builder.create_vector_from_iter(v.iter().cloned().map(Into::<FbsBlock>::into));
            dictionaries_offset
        });
        let recordBatches_offset = self.recordBatches.as_ref().map(|v| {
            let recordBatches_offset =
                builder.create_vector_from_iter(v.iter().cloned().map(Into::<FbsBlock>::into));
            recordBatches_offset
        });
        let schema_offset = self.schema.as_ref().map(|o| o.serialize_to(builder));

        let mut bldr = FbsFooterBuilder::new(builder);
        if let Some(offset) = custom_metadata_offset {
            bldr.add_custom_metadata(offset);
        }
        if let Some(offset) = dictionaries_offset {
            bldr.add_dictionaries(offset);
        }
        if let Some(offset) = recordBatches_offset {
            bldr.add_recordBatches(offset);
        }
        if let Some(offset) = schema_offset {
            bldr.add_schema(offset);
        }
        bldr.add_version(FbsMetadataVersion::from(self.version));
        bldr.finish()
    }
}

impl From<FbsFooter<'_>> for Footer {
    fn from(fbs: FbsFooter<'_>) -> Self {
        let custom_metadata = if let Some(val) = fbs.custom_metadata() {
            let mut custom_metadata = Vec::new();
            for elem in val {
                custom_metadata.push(elem.into());
            }

            Some(custom_metadata)
        } else {
            None
        };

        let dictionaries = if let Some(val) = fbs.dictionaries() {
            let mut dictionaries = Vec::new();
            for elem in val {
                dictionaries.push(elem.into());
            }

            Some(dictionaries)
        } else {
            None
        };

        let recordBatches = if let Some(val) = fbs.recordBatches() {
            let mut recordBatches = Vec::new();
            for elem in val {
                recordBatches.push(elem.into());
            }

            Some(recordBatches)
        } else {
            None
        };

        let schema = fbs.schema().map(Schema::from);
        let version = MetadataVersion::from(fbs.version());
        Self {
            custom_metadata,
            dictionaries,
            recordBatches,
            schema,
            version,
        }
    }
}

impl crate::FbsSerde for Footer {
    fn to_fbs_bytes(&self) -> Vec<u8> {
        let mut bldr = flatbuffers::FlatBufferBuilder::new();
        let offset = self.serialize_to(&mut bldr);
        bldr.finish_size_prefixed(offset, None);
        bldr.finished_data().to_vec()
    }

    fn from_fbs_bytes(bytes: &[u8]) -> Result<Self, flatbuffers::InvalidFlatbuffer> {
        let opts = flatbuffers::VerifierOptions {
            max_tables: 100_000_000,
            ..Default::default()
        };
        let fbs = flatbuffers::size_prefixed_root_with_opts::<FbsFooter>(&opts, bytes)?;
        Ok(Self::from(fbs))
    }
}

